import axios, { type AxiosInstance, type InternalAxiosRequestConfig } from 'axios'

const API_TIMEOUT = 10000

// Always use relative /api so requests go through the Vite proxy in dev
// and through Nginx in production.
const API_BASE_URL = import.meta.env.VITE_API_URL ?? '/api'

// Exact paths that are publicly accessible — no redirect to /login on auth loss.
const PUBLIC_EXACT_PATHS = new Set([
  '/', '/login', '/register',
  '/forgot-password', '/reset-password',
  '/verify-email', '/verify-email-sent',
  '/dashboard',   // public browse
  '/forum',       // forum listing
])
// Path prefixes that are also public (dynamic routes)
const PUBLIC_PREFIX_PATHS = [
  '/service-detail/',
  '/public-profile/',
  '/forum/',
]
const isPublicPath = () => {
  const p = window.location.pathname
  return PUBLIC_EXACT_PATHS.has(p) || PUBLIC_PREFIX_PATHS.some((prefix) => p.startsWith(prefix))
}


export const apiClient: AxiosInstance = axios.create({
  baseURL: API_BASE_URL,
  headers: { 'Content-Type': 'application/json' },
  timeout: API_TIMEOUT,
  withCredentials: true, // send cookies with every request
})

// ─── Token Refresh Queue ────────────────────────────────────────────────────
let isRefreshing = false
let refreshPromise: Promise<void> | null = null
let failedQueue: Array<{
  resolve: (value?: unknown) => void
  reject: (error: unknown) => void
}> = []

const processQueue = (error: unknown) => {
  failedQueue.forEach((prom) => {
    if (error) prom.reject(error)
    else prom.resolve()
  })
  failedQueue = []
}

// ─── Request Interceptor ─────────────────────────────────────────────────────
// Auth is handled exclusively via cookies (CookieJWTAuthentication on the backend).
// Do NOT attach Authorization header — stale cookies in the header would cause
// JWTAuthentication to raise AuthenticationFailed on public endpoints like /register.
apiClient.interceptors.request.use(
  (config: InternalAxiosRequestConfig) => config,
  (error) => Promise.reject(error),
)

// ─── Response Interceptor: auto-refresh on 401 ──────────────────────────────
apiClient.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config
    const requestUrl: string = originalRequest?.url ?? ''

    const isAuthEndpoint = (url: string) =>
      url.includes('/auth/login/') ||
      url.includes('/auth/register/') ||
      url.includes('/auth/refresh/') ||
      url.includes('/auth/logout/')

    if (error.response?.status === 401 && !originalRequest._retry) {
      if (isAuthEndpoint(requestUrl)) return Promise.reject(error)

      // Check if we have a refresh_token cookie (httponly, can't read value but presence check via request)
      originalRequest._retry = true

      if (isRefreshing) {
        return new Promise((resolve, reject) => {
          failedQueue.push({ resolve, reject })
        })
          .then(() => apiClient(originalRequest))
          .catch((err) => Promise.reject(err))
      }

      isRefreshing = true

      if (!refreshPromise) {
        refreshPromise = (async () => {
          try {
            // Backend reads refresh_token cookie, returns new access_token cookie
            await axios.post(
              `${API_BASE_URL}/auth/refresh/`,
              {},
              { withCredentials: true },
            )
            processQueue(null)
          } catch (refreshError: unknown) {
            processQueue(refreshError)
            const e = refreshError as { response?: { status?: number } }
            // Only redirect if refresh definitively failed AND user is on a protected page.
            // Never redirect on public pages — that causes an infinite reload loop.
            if (
              [400, 401, 403].includes(e.response?.status ?? 0) &&
              !isPublicPath()
            ) {
              window.location.href = '/login?error=session_expired'
            }
            throw refreshError
          } finally {
            isRefreshing = false
            refreshPromise = null
          }
        })()
      }

      try {
        await refreshPromise
        // New access_token cookie is now set — just retry, cookie is sent automatically
        return apiClient(originalRequest)
      } catch (refreshError) {
        return Promise.reject(refreshError)
      }
    }

    return Promise.reject(error)
  },
)

// ─── Error Types ─────────────────────────────────────────────────────────────
export interface ApiErrorResponse {
  detail: string
  code: string
  field_errors?: Record<string, string[]>
  error?: string
  message?: string
  [key: string]: unknown
}

export interface ApiError extends Error {
  response?: {
    data?: ApiErrorResponse
    status?: number
  }
}

export function getErrorMessage(
  error: unknown,
  defaultMessage = 'An unexpected error occurred.',
): string {
  if (typeof error === 'string') return error

  if (error && typeof error === 'object') {
    const e = error as ApiError
    if (e.response?.data) {
      const data = e.response.data

      // DRF field validation errors: { email: ["..."], password: ["..."] }
      // (no 'detail' key, just field→string[] pairs)
      if (typeof data === 'object' && !Array.isArray(data)) {
        const knownTopKeys = new Set(['detail', 'code', 'field_errors', 'error', 'message', 'messages'])
        const fieldKeys = Object.keys(data).filter((k) => !knownTopKeys.has(k))
        const inlineFieldErrors = fieldKeys
          .map((k) => {
            const v = (data as Record<string, unknown>)[k]
            if (Array.isArray(v)) return v.join(', ')
            if (typeof v === 'string') return v
            return null
          })
          .filter(Boolean) as string[]

        // detail is present — primary message
        const detail = typeof data.detail === 'string' ? data.detail : ''

        // field_errors from our own error format
        const fieldErrors: string[] = []
        if (data.field_errors) {
          for (const [, errors] of Object.entries(data.field_errors)) {
            if (Array.isArray(errors)) fieldErrors.push(errors.join(', '))
          }
        }

        // Combine all available field messages
        const allFieldErrors = [...inlineFieldErrors, ...fieldErrors]

        if (detail) return allFieldErrors.length ? `${detail}: ${allFieldErrors.join('. ')}` : detail
        if (allFieldErrors.length) return allFieldErrors.join('. ')
        if (data.error) return String(data.error)
        if (data.message) return String(data.message)
      }

      // DRF token/auth errors: { detail: "...", code: "...", messages: [...] }
      if (typeof data.detail === 'string') return data.detail
    }
    if (e.message) return e.message
  }

  return defaultMessage
}

export default apiClient

src/services/conversationAPI.ts.source:
import apiClient from './api'

// ─── Types ────────────────────────────────────────────────────────────────────

export interface ApiChatMessage {
  id: string
  handshake: string
  handshake_id: string
  sender: string         // UUID
  sender_id: string
  sender_name: string
  sender_avatar_url: string | null
  body: string
  created_at: string
}

export interface PublicChatMessage {
  id: string
  room: string
  sender_id: string
  sender_name: string
  sender_avatar_url: string | null
  body: string
  created_at: string
}

interface PublicChatRoom {
  id: string
  name: string
  type: string
  related_service: string | null
  created_at: string
}

export interface ChatConversation {
  handshake_id: string
  service_id: string
  service_title: string
  service_type: string   // 'Offer' | 'Need'
  other_user: {
    id: string
    name: string
    avatar_url: string | null
  }
  last_message: ApiChatMessage | null
  status: string
  is_provider: boolean
  provider_confirmed_complete: boolean
  receiver_confirmed_complete: boolean
  provider_initiated: boolean
  requester_initiated: boolean
  updated_at: string | null
  evaluation_window_starts_at: string | null
  evaluation_window_ends_at: string | null
  evaluation_window_closed_at: string | null
  exact_location: string | null
  exact_location_maps_url?: string | null
  exact_location_guide?: string | null
  exact_duration: number | null
  scheduled_time: string | null
  service_location_type?: string | null
  service_location_area?: string | null
  service_exact_location?: string | null
  service_exact_location_maps_url?: string | null
  service_location_guide?: string | null
  service_scheduled_time?: string | null
  provisioned_hours: number | null
  user_has_reviewed: boolean
  max_participants: number
  schedule_type: string  // 'One-Time' | 'Recurrent'
  service_member_count?: number
  cancellation_requested_by_id?: string | null
  cancellation_requested_by_name?: string | null
  cancellation_requested_at?: string | null
  cancellation_reason?: string | null
  can_request_cancellation?: boolean
  can_respond_to_cancellation?: boolean
}

export interface GroupChatMessage {
  id: string
  service: string
  sender_id: string
  sender_name: string
  sender_avatar_url: string | null
  body: string
  created_at: string
}

export interface GroupChatParticipant {
  id: string
  name: string
  avatar_url: string | null
}

export interface GroupChatSessionSummary {
  id: string
  scheduled_time: string
}

export interface GroupChatThreadData {
  service_id: string
  service_title: string
  participants: GroupChatParticipant[]
  messages: GroupChatMessage[]
  session_id?: string
  scheduled_time?: string
}

interface MessagesResponse {
  count: number
  next: string | null
  previous: string | null
  results: ApiChatMessage[]
}

// ─── API ──────────────────────────────────────────────────────────────────────

export const conversationAPI = {
  /**
   * GET /api/chats/ — list all conversations for the authenticated user.
   * Returns conversations ordered by most-recently-updated handshake.
   */
  listConversations: async (signal?: AbortSignal): Promise<ChatConversation[]> => {
    const res = await apiClient.get<ChatConversation[] | { results: ChatConversation[] }>(
      '/chats/',
      { signal, params: { force: 1 } },
    )
    const data = res.data
    return Array.isArray(data) ? data : (data.results ?? [])
  },

  /**
   * GET /api/chats/:handshakeId/ — fetch messages for a conversation.
   * Backend returns newest-first; caller should reverse for chronological display.
   */
  getMessages: async (
    handshakeId: string,
    signal?: AbortSignal,
    pageSize = 50,
  ): Promise<ApiChatMessage[]> => {
    const res = await apiClient.get<MessagesResponse>(`/chats/${handshakeId}/`, {
      params: { page_size: pageSize },
      signal,
    })
    return res.data.results ?? []
  },

  /**
   * POST /api/chats/ — send a message.
   * Body: { handshake_id, body }
   */
  sendMessage: async (handshakeId: string, body: string): Promise<ApiChatMessage> => {
    const res = await apiClient.post<ApiChatMessage>('/chats/', {
      handshake_id: handshakeId,
      body,
    })
    return res.data
  },
}

export const groupChatAPI = {
  /**
   * GET /api/group-chat/{serviceId}/?list_sessions=1 — list sessions for recurrent group chat.
   */
  getSessions: async (serviceId: string, signal?: AbortSignal): Promise<GroupChatSessionSummary[]> => {
    const res = await apiClient.get<{ sessions: GroupChatSessionSummary[] }>(
      `/group-chat/${serviceId}/`,
      { signal, params: { list_sessions: 1 } },
    )
    return res.data.sessions ?? []
  },

  /**
   * GET /api/group-chat/{serviceId}/ — last 50 messages. For recurrent, pass sessionId.
   */
  getMessages: async (
    serviceId: string,
    signal?: AbortSignal,
    sessionId?: string | null,
  ): Promise<GroupChatThreadData> => {
    const params = sessionId ? { session_id: sessionId } : {}
    const res = await apiClient.get<GroupChatThreadData>(
      `/group-chat/${serviceId}/`,
      { signal, params },
    )
    return {
      service_id: res.data.service_id,
      service_title: res.data.service_title,
      participants: res.data.participants ?? [],
      messages: res.data.messages ?? [],
      session_id: res.data.session_id,
      scheduled_time: res.data.scheduled_time,
    }
  },

  /**
   * POST /api/group-chat/{serviceId}/ — send a message. For recurrent, pass sessionId.
   */
  sendMessage: async (
    serviceId: string,
    body: string,
    sessionId?: string | null,
  ): Promise<GroupChatMessage> => {
    const payload = sessionId ? { body, session_id: sessionId } : { body }
    const res = await apiClient.post<GroupChatMessage>(`/group-chat/${serviceId}/`, payload)
    return res.data
  },
}

// ─── Event Chat API (public chat rooms) ───────────────────────────────────────

export const eventChatAPI = {
  /**
   * GET /api/public-chat/{serviceId}/ — get room info and messages for an event.
   * Returns { room, messages: { count, next, previous, results } }.
   */
  getMessages: async (serviceId: string, signal?: AbortSignal): Promise<{ room: PublicChatRoom; messages: PublicChatMessage[] }> => {
    const res = await apiClient.get<{ room: PublicChatRoom; messages: { results: PublicChatMessage[] } }>(
      `/public-chat/${serviceId}/`,
      { signal },
    )
    return {
      room: res.data.room,
      messages: res.data.messages?.results ?? [],
    }
  },

  /**
   * POST /api/public-chat/{serviceId}/ — send a message to the event chat.
   */
  sendMessage: async (serviceId: string, body: string): Promise<PublicChatMessage> => {
    const res = await apiClient.post<PublicChatMessage>(`/public-chat/${serviceId}/`, { body })
    return res.data
  },
}

// Both dev and prod connect to the current host; the WS upgrade is forwarded
// by Vite's /ws proxy rule (dev) or Nginx (prod). This respects VITE_BACKEND_URL
// without hard-coding a port and works in Docker / LAN setups.
const wsBase = `${window.location.protocol === 'https:' ? 'wss' : 'ws'}://${window.location.host}`

export const buildChatWsUrl      = (id: string) => `${wsBase}/ws/chat/${id}/`
export const buildGroupChatWsUrl = (serviceId: string, sessionId?: string | null) =>
  sessionId
    ? `${wsBase}/ws/group-chat/${serviceId}/?session_id=${encodeURIComponent(sessionId)}`
    : `${wsBase}/ws/group-chat/${serviceId}/`
export const buildEventChatWsUrl = (roomId: string) => `${wsBase}/ws/public-chat/${roomId}/`

