/**
 * Tests for useNotificationStore.
 *
 * Exercises addNotification (dedup), markAsRead (optimistic update + revert),
 * markAllAsRead (optimistic update + revert), and reset.
 */
import { describe, it, expect, vi, beforeEach } from 'vitest'
import type { Notification } from '@/types'

const markAsReadAPIMock = vi.fn().mockResolvedValue(undefined)
const markAllAsReadAPIMock = vi.fn().mockResolvedValue(undefined)
const listAPIMock = vi.fn()
const unreadCountAPIMock = vi.fn().mockResolvedValue(3)

vi.mock('@/services/notificationAPI', () => ({
  notificationAPI: {
    list: listAPIMock,
    unreadCount: unreadCountAPIMock,
    markAsRead: markAsReadAPIMock,
    markAllAsRead: markAllAsReadAPIMock,
  },
}))

function makeNotification(id: string, is_read = false): Notification {
  return {
    id,
    type: 'handshake_request',
    title: `Notification ${id}`,
    message: 'msg',
    is_read,
    related_handshake: null,
    related_service: null,
    related_service_type: null,
    related_report: null,
    related_user: null,
    created_at: '2026-01-01T00:00:00Z',
  }
}

describe('useNotificationStore', () => {
  beforeEach(() => {
    vi.resetModules()
    markAsReadAPIMock.mockResolvedValue(undefined)
    markAllAsReadAPIMock.mockResolvedValue(undefined)
  })

  it('addNotification prepends new notification and increments unreadCount', async () => {
    const { useNotificationStore } = await import('@/store/useNotificationStore')
    const store = useNotificationStore.getState()
    store.reset()

    const n = makeNotification('n1')
    store.addNotification(n)

    const state = useNotificationStore.getState()
    expect(state.notifications[0].id).toBe('n1')
    expect(state.unreadCount).toBe(1)
  })

  it('addNotification ignores duplicate ids', async () => {
    const { useNotificationStore } = await import('@/store/useNotificationStore')
    const store = useNotificationStore.getState()
    store.reset()

    const n = makeNotification('n2')
    store.addNotification(n)
    store.addNotification(n)

    const state = useNotificationStore.getState()
    expect(state.notifications.length).toBe(1)
    expect(state.unreadCount).toBe(1)
  })

  it('markAsRead optimistically marks notification as read and decrements count', async () => {
    const { useNotificationStore } = await import('@/store/useNotificationStore')
    const store = useNotificationStore.getState()
    store.reset()
    store.addNotification(makeNotification('n3', false))

    await store.markAsRead('n3')

    const state = useNotificationStore.getState()
    expect(state.notifications.find((n) => n.id === 'n3')?.is_read).toBe(true)
    expect(state.unreadCount).toBe(0)
    expect(markAsReadAPIMock).toHaveBeenCalledWith('n3')
  })

  it('markAsRead reverts on API failure', async () => {
    markAsReadAPIMock.mockRejectedValueOnce(new Error('network'))
    const { useNotificationStore } = await import('@/store/useNotificationStore')
    const store = useNotificationStore.getState()
    store.reset()
    store.addNotification(makeNotification('n4', false))

    await store.markAsRead('n4')

    const state = useNotificationStore.getState()
    expect(state.notifications.find((n) => n.id === 'n4')?.is_read).toBe(false)
    expect(state.unreadCount).toBe(1)
  })

  it('markAllAsRead marks every notification as read and zeroes unreadCount', async () => {
    const { useNotificationStore } = await import('@/store/useNotificationStore')
    const store = useNotificationStore.getState()
    store.reset()
    store.addNotification(makeNotification('n5'))
    store.addNotification(makeNotification('n6'))

    await store.markAllAsRead()

    const state = useNotificationStore.getState()
    expect(state.notifications.every((n) => n.is_read)).toBe(true)
    expect(state.unreadCount).toBe(0)
    expect(markAllAsReadAPIMock).toHaveBeenCalled()
  })

  it('markAllAsRead reverts on API failure', async () => {
    markAllAsReadAPIMock.mockRejectedValueOnce(new Error('network'))
    const { useNotificationStore } = await import('@/store/useNotificationStore')
    const store = useNotificationStore.getState()
    store.reset()
    store.addNotification(makeNotification('n7', false))

    await store.markAllAsRead()

    const state = useNotificationStore.getState()
    expect(state.notifications.find((n) => n.id === 'n7')?.is_read).toBe(false)
  })

  it('reset clears all state', async () => {
    const { useNotificationStore } = await import('@/store/useNotificationStore')
    const store = useNotificationStore.getState()
    store.addNotification(makeNotification('n8'))
    store.reset()

    const state = useNotificationStore.getState()
    expect(state.notifications).toHaveLength(0)
    expect(state.unreadCount).toBe(0)
    expect(state.hasMore).toBe(true)
    expect(state.currentPage).toBe(0)
  })

  it('fetchUnreadCount updates unreadCount from API', async () => {
    const { useNotificationStore } = await import('@/store/useNotificationStore')
    const store = useNotificationStore.getState()
    store.reset()

    await store.fetchUnreadCount()

    expect(useNotificationStore.getState().unreadCount).toBe(3)
  })
})

src/test/components/ServiceEvaluationMod.source:
import { ChakraProvider } from '@chakra-ui/react'
import { fireEvent, render, screen, waitFor } from '@testing-library/react'
import type { ComponentProps } from 'react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'

import ServiceEvaluationModal from '@/components/ServiceEvaluationModal'
import system from '@/theme'

/**
 * NFR-14d — when a photo upload fails after the evaluation itself has
 * persisted, the modal must close with a non-blocking warning toast
 * (instead of stranding the user with a generic error and an open modal
 * that no longer needs their attention). These tests pin both the
 * generic-failure and the file-too-large (413) paths.
 */

const { submitCombinedMock, attachReviewImagesMock, toastSuccessMock, toastErrorMock } =
  vi.hoisted(() => ({
    submitCombinedMock: vi.fn(),
    attachReviewImagesMock: vi.fn(),
    toastSuccessMock: vi.fn(),
    toastErrorMock: vi.fn(),
  }))

vi.mock('@/services/reputationAPI', () => ({
  reputationAPI: {
    submitCombined: submitCombinedMock,
    submitCombinedEvent: vi.fn(),
    attachReviewImages: attachReviewImagesMock,
  },
}))

vi.mock('sonner', () => ({
  toast: { success: toastSuccessMock, error: toastErrorMock },
}))

function renderModal(props: Partial<ComponentProps<typeof ServiceEvaluationModal>> = {}) {
  const onClose = props.onClose ?? vi.fn()
  const onSubmitted = props.onSubmitted ?? vi.fn()
  const utils = render(
    <ChakraProvider value={system}>
      <ServiceEvaluationModal
        isOpen
        onClose={onClose}
        onSubmitted={onSubmitted}
        handshakeId="hs-1"
        counterpartName="Cem"
        {...props}
      />
    </ChakraProvider>,
  )
  return { ...utils, onClose, onSubmitted }
}

function attachOneImage(): void {
  // The modal renders an <input type="file"> hidden behind the "Add photos"
  // button. Drive it directly via fireEvent so we don't need user-event's
  // pointer simulation.
  const input = document.querySelector('input[type="file"]') as HTMLInputElement | null
  expect(input).not.toBeNull()
  const file = new File(['x'], 'photo.jpg', { type: 'image/jpeg' })
  fireEvent.change(input!, { target: { files: [file] } })
}

function selectFirstPositiveTrait(): void {
  // Trait toggles are buttons with their label text. "Punctual" is the
  // first positive service trait and is always rendered.
  fireEvent.click(screen.getByRole('button', { name: /Punctual/i }))
}

async function clickSubmit(): Promise<void> {
  const submit = await screen.findByRole('button', { name: /submit evaluation/i })
  fireEvent.click(submit)
}

describe('ServiceEvaluationModal — photo upload failure (NFR-14d)', () => {
  beforeEach(() => {
    submitCombinedMock.mockReset().mockResolvedValue(undefined)
    attachReviewImagesMock.mockReset()
    toastSuccessMock.mockReset()
    toastErrorMock.mockReset()
  })

  afterEach(() => {
    vi.clearAllMocks()
  })

  it('closes the modal with a non-blocking warning when the upload fails generically', async () => {
    attachReviewImagesMock.mockRejectedValue(new Error('network'))
    const { onClose, onSubmitted } = renderModal()

    selectFirstPositiveTrait()
    attachOneImage()
    await clickSubmit()

    await waitFor(() => {
      expect(submitCombinedMock).toHaveBeenCalledTimes(1)
    })
    await waitFor(() => {
      expect(attachReviewImagesMock).toHaveBeenCalledTimes(1)
    })

    // The warning toast must explicitly say the evaluation persisted so
    // the user knows the trait/comment they typed is not lost.
    await waitFor(() => {
      expect(toastErrorMock).toHaveBeenCalled()
    })
    const errorMsg = toastErrorMock.mock.calls.at(-1)?.[0] as string
    expect(errorMsg).toMatch(/your evaluation was saved/i)

    // The success path still fires (close + onSubmitted) — that's the
    // behavioural contract NFR-14d asserts.
    expect(toastSuccessMock).toHaveBeenCalled()
    expect(onSubmitted).toHaveBeenCalled()
    expect(onClose).toHaveBeenCalled()
  })

  it('uses the file-too-large copy when the upload returns 413', async () => {
    attachReviewImagesMock.mockRejectedValue({ response: { status: 413 } })
    const { onClose } = renderModal()

    selectFirstPositiveTrait()
    attachOneImage()
    await clickSubmit()

    await waitFor(() => {
      expect(toastErrorMock).toHaveBeenCalled()
    })
    const errorMsg = toastErrorMock.mock.calls.at(-1)?.[0] as string
    expect(errorMsg).toMatch(/files are too large/i)
    expect(errorMsg).toMatch(/your evaluation was saved without photos/i)

    // Close path still runs — same NFR-14d contract.
    expect(onClose).toHaveBeenCalled()
  })

  it('does not call attachReviewImages when no images are attached', async () => {
    const { onSubmitted, onClose } = renderModal()

    selectFirstPositiveTrait()
    await clickSubmit()

    await waitFor(() => {
      expect(submitCombinedMock).toHaveBeenCalledTimes(1)
    })
    expect(attachReviewImagesMock).not.toHaveBeenCalled()
    expect(toastSuccessMock).toHaveBeenCalled()
    expect(onSubmitted).toHaveBeenCalled()
    expect(onClose).toHaveBeenCalled()
  })
})

