    service_title: 'Neighborhood Picnic',
    service_type: 'Event',
    requester: 'user-2',
    requester_name: 'Deniz Guest',
    provider_name: 'Aylin Host',
    status: 'checked_in',
    provisioned_hours: 0,
    provider_confirmed_complete: false,
    receiver_confirmed_complete: false,
