    await waitFor(() => {
      expect(screen.getByText('Beginner chess coaching')).toBeInTheDocument()
    })
    expect(screen.getByText('Bake bread together')).toBeInTheDocument()
  })

  it('removes a card from the list when the user unsaves it', async () => {
